referenceSolutions.javascript:
export function wordBreak(text        , words          )          {
const ok          =Array(text.length+1).fill(false);ok[0]=true;for(let i=1;i<=text.length;i++)for(const w of words)if(i>=w.length&&ok[i-w.length]&&text.slice(i-w.length,i)===w)ok[i]=true;return ok[text.length];
}

